-- =====================================================
-- 03_data.sql - Datos iniciales del taller
-- Datos realistas de un taller en Colombia (precios aproximados en COP).
-- Las cédulas, teléfonos y placas (excepto la de Rodolfa) son inventados.
-- Se puede ejecutar varias veces: primero limpia y reinicia los id.
-- =====================================================
SET DEFINE OFF;

-- ===== LIMPIEZA (de hijas a padres) =====
DELETE FROM movimientos;
DELETE FROM trabajos;
DELETE FROM repuestos;
DELETE FROM motos_cliente;
DELETE FROM clientes;
DELETE FROM marcas;
DELETE FROM categorias;
DELETE FROM usuarios;
DELETE FROM roles;

ALTER TABLE roles         MODIFY (id_rol        GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE usuarios      MODIFY (id_usuario    GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE categorias    MODIFY (id_categoria  GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE marcas        MODIFY (id_marca      GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE clientes      MODIFY (id_cliente    GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE motos_cliente MODIFY (id_moto       GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE repuestos     MODIFY (id_repuesto   GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE trabajos      MODIFY (id_trabajo    GENERATED BY DEFAULT AS IDENTITY (START WITH 1));
ALTER TABLE movimientos   MODIFY (id_movimiento GENERATED BY DEFAULT AS IDENTITY (START WITH 1));

